  window.__sub = sub;
  const info = () => { const P = g.prologue; const S = P.set; return { pd: +(window.__pd || 0).toFixed(2), pn: window.__pn, sc: P.sceneN, t: +P.sceneT.toFixed(2), shotT: P.shots && P.shots.t ? +P.shots.t.toFixed(2) : null, sub: sub().slice(0, 60), er: S && S.erasing ? +S.erasing.t.toFixed(2) : null, k: S && S.erasing ? S.erasing.k : null, gone: S ? S.wheelGone : null }; };
  window.__info = info;
  const idle = () => new Promise((r) => setTimeout(r, 0));
  window.__until = async (fn, cap = 60) => { let n = 0; while (n < 30 * cap && !fn()) { step(1); n++; if (n % 20 === 0) await idle(); } return Object.assign({ n }, info()); };
  window.__untilSub = async (re, after = 0, cap = 60) => { const r = new RegExp(re); const o = await window.__until(() => r.test(sub()), cap); step(Math.round(after * 30)); return Object.assign(o, info()); };
  g.input.lockFailed = true;
  const P0 = g.prologue;
  const ou = P0.update.bind(P0);
  window.__pd = 0; window.__pn = 0;
  P0.update = (dt) => { window.__pd += dt; window.__pn++; return ou(dt); };
  window.__subs = [];
  const tickSub = () => { const s = sub(); const l = window.__subs[window.__subs.length - 1]; if (s && (!l || l[1] !== s)) window.__subs.push([+(P0.clock || 0).toFixed(2), s.slice(0, 40), window.__pn]); };
  const gu = g.update.bind(g);
  g.update = (dt) => { const r = gu(dt); tickSub(); return r; };
  return window.__until(() => g.prologue.sceneN >= 2 && g.prologue.castReady, 30);
})()

